#!/usr/bin/env python3
"""Scaffold a business-glossary repo (or report what is already there).

  bg_init.py ./my-glossary --name "Acme Glossary" --languages en,pl
  bg_init.py ./g --profile minimal --dry-run
"""

import argparse
import os
import shutil
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from bg_core import (CONFIG_NAME, PROFILES_DIR, SKILL_DIR, dump_yaml,
                     write_text)

MAKEFILE = """\
# Generated by business-glossary init. The repo is canonical.
SK ?= {skill}/scripts
PY ?= python3

validate:
\t$(PY) $(SK)/bg_validate.py --repo .
build:
\t$(PY) $(SK)/bg_site.py --repo .
relations:
\t$(PY) $(SK)/bg_relations.py --repo . --dry-run
all: validate build
"""

README = """\
---
title: {name}
summary: Business glossary repo with one Markdown file per term and
  generated search and graph views.
---

# {name}

- `terms/<id>.md` is canonical; one file per term, ids never change.
- `generated/` is derived (open `generated/site/index.html` offline).
- `rules/profile.yaml` is the rule set; swap it per repo.
- Scripts live in the business-glossary skill; see the Makefile.
"""


def git_email():
  import subprocess
  try:
    out = subprocess.run(['git', 'config', 'user.email'], text=True,
                         capture_output=True).stdout.strip()
  except OSError:
    out = ''
  return out or 'you@example.com'


def main():
  ap = argparse.ArgumentParser(description=__doc__.split('\n')[0])
  ap.add_argument('path', help='folder for the new glossary repo')
  ap.add_argument('--name', default='Business Glossary')
  ap.add_argument('--languages', default='en',
                  help='comma list, en and/or pl (default en)')
  ap.add_argument('--profile', default='minimal',
                  help='profile name from assets/profiles or a YAML path '
                       '(default minimal; standard is planned)')
  ap.add_argument('--dry-run', action='store_true')
  a = ap.parse_args()

  langs = [x.strip() for x in a.languages.split(',') if x.strip()]
  bad = [x for x in langs if x not in ('en', 'pl')]
  if bad:
    sys.exit('unsupported language(s): %s' % bad)
  if a.profile.replace('.yaml', '') == 'standard':
    sys.exit('the standard profile is planned and not yet available '
             '(see SPEC.md 5.3); use --profile minimal')
  prof_src = a.profile if os.path.isfile(a.profile) else os.path.join(
    PROFILES_DIR, a.profile.replace('.yaml', '') + '.yaml')
  if not os.path.isfile(prof_src):
    sys.exit('profile not found: %s' % a.profile)
  root = os.path.abspath(a.path)
  if os.path.isfile(os.path.join(root, CONFIG_NAME)):
    sys.exit('already a glossary repo: %s (use bg_update.py)' % root)

  cfg = {
    'name': a.name, 'languages': langs, 'primary_language': langs[0],
    'profile': 'rules/profile.yaml', 'terms_dir': 'terms',
    'default_type': 'Concept', 'polish_required': False,
    'defaults': {'author': os.environ.get('BG_AUTHOR') or git_email()},
    'profile_options': {}, 'sources': [],
  }
  plan = [
    (CONFIG_NAME, dump_yaml(cfg)),
    ('README.md', README.format(name=a.name)),
    ('Makefile', MAKEFILE.format(skill=SKILL_DIR)),
    ('.gitignore', 'generated/\n.glossary/cache/\n'),
    ('terms/.gitkeep', ''),
    ('.glossary/ids.lock', ''),
  ]
  for rel, _ in plan:
    print('%s %s' % ('would create' if a.dry_run else 'create', rel))
  print('%s rules/profile.yaml (from %s)' % (
    'would copy' if a.dry_run else 'copy', os.path.basename(prof_src)))
  if a.dry_run:
    return
  for rel, text in plan:
    write_text(os.path.join(root, rel), text)
  os.makedirs(os.path.join(root, 'rules'), exist_ok=True)
  shutil.copyfile(prof_src, os.path.join(root, 'rules', 'profile.yaml'))
  print('\nnext: add sources (bg_discover.py --repo %s --ask)' % root)


if __name__ == '__main__':
  main()
